from research_helpers import *
Q=ev('https://ir.genmab.com/node/49531/html','May2026 issuer pipeline and royalty portfolio. Commercial-partner links below denote royalty/licensing relationships, not manufacture or original invention. Distinct combination formulations retained separately.')
T=ev('https://ir.genmab.com/node/48596/html','Issuer describes four named antibody platforms plus ProfoundBio ADC platforms; generic ADC category not invented as an additional named technology.')
D=ev('https://ir.genmab.com/news-releases/news-release-details/genmab-portfolio-prioritization-update/','December29 2025 issuer confirms discontinued acasunlimab development.')
H=ev('https://ir.genmab.com/node/45356/html','Historical issuer identifies acasunlimab as GEN1046/BNT311, distinct from other BioNTech programmes.')
ps=[]
for n,d,life,als,roles in [('EPKINLY','CD3/CD20 antibody.','commercial',['TEPKINLY','epcoritamab'],['developer']),('TIVDAK','Tissue-factor ADC.','commercial',['tisotumab vedotin'],['developer']),('Rinatabart sesutecan','Folate-receptor ADC.','development',['Rina-S','GEN1184'],['owner']),('Petosemtamab','EGFR/LGR5 antibody.','development',[],['owner']),('GEN1059','EpCAM/4-1BB antibody.','development',['BNT314'],['developer']),('GEN1057','Investigational antibody.','development',[],['developer']),('GEN3018','Investigational antibody.','development',[],['developer']),('GEN1079','Investigational antibody.','development',[],['developer']),('GEN1106','Investigational ADC.','development',[],['developer'])]:ps.append(p(n,d,Q,life,roles=roles,aliases=als,typ='product'if life=='commercial'else'development_program'))
for n,d in [('DARZALEX','Daratumumab IV.'),('DARZALEX FASPRO','Daratumumab/hyaluronidase SC.'),('Kesimpta','Ofatumumab.'),('TEPEZZA','Teprotumumab.'),('RYBREVANT','Amivantamab.'),('RYBREVANT FASPRO','Amivantamab/hyaluronidase.'),('TECVAYLI','Teclistamab.'),('TALVEY','Talquetamab.'),('BIZENGRI','Zenocutuzumab.')]:ps.append(p(n,d,Q,'commercial',roles=['commercial_partner'],typ='product',attributes={'relationship_scope':'royalty_and_licensing_portfolio'}))
for n,als in [('Denecimig',['Mim9']),('Amlenetug',[]),('INCA33890',[])]:ps.append(p(n,'Partner-led investigational antibody.',Q,'development',roles=['commercial_partner'],aliases=als,attributes={'relationship_scope':'royalty_and_licensing_portfolio'}))
for n,d in [('DuoBody','Bispecific-antibody platform.'),('HexaBody','Antibody hexamerization platform.'),('DuoHexaBody','Bispecific hexamerization platform.'),('HexElect','Co-dependent antibody platform.')]:ps.append(p(n,d,T,roles=['developer'],typ='technology'))
ps.append(p('Acasunlimab','Historical PD-L1/4-1BB bispecific antibody.',H,'discontinued',aliases=['GEN1046','BNT311'],evidence=[H,D]))
cs=[company('Genmab',ps,[Q,T,D,H],'26 named products/programmes/platforms captured from issuer evidence, distinguishing proprietary development, acquired ownership and royalty relationships. Regional brand aliases consolidated; hyaluronidase combinations separate. Acasunlimab discontinued. Older programmes, acquired Merus/ProfoundBio assets and further partner pipeline require followup.')]
(out/'batch-0053.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
